#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<int> v(n);
    vector<int> present;
    vector<bool> seen(n + 1, false);

    for (int i = 0; i < n; ++i) {
        cin >> v[i];
        if (!seen[v[i]]) {
            seen[v[i]] = true;
            present.push_back(v[i]);
        }
    }

    if (present.size() <= 1) {
        cout << 1 << "\n";
        return 0;
    }

    int max_len = 1;

    for (size_t i = 0; i < present.size(); ++i) {
        for (size_t j = i + 1; j < present.size(); ++j) {
            int a = present[i];
            int b = present[j];
            int current_len = 0;
            int last = -1;

            for (int k = 0; k < n; ++k) {
                if (v[k] == a || v[k] == b) {
                    if (v[k] != last) {
                        current_len++;
                        last = v[k];
                    }
                }
            }
            max_len = max(max_len, current_len);
        }
    }

    cout << max_len << "\n";

    return 0;
}
